@classmethod
def from_neurodata_object(cls, neurodata_object: Container, dataset_name: Literal["data", "timestamps"]) -> Self:
    candidate_dataset = getattr(neurodata_object, dataset_name)
    if isinstance(candidate_dataset, h5py.Dataset):
        return cls.from_existing_neurodata_object(neurodata_object=neurodata_object, dataset_name=dataset_name)

    return super().from_neurodata_object(neurodata_object=neurodata_object, dataset_name=dataset_name)
